#include <bits/stdc++.h>
using namespace std;

const int MOD1=998244353;
const int MOD2=1000000007;
long long total_value;
int digit_array[15], base_array[15], total_ans;

long long get_number(int *arr, int len){
    long long res=0;
    for (int i=1; i<=len; i++)
        res=res*10+arr[i];
    return res;
}

long long calculate_rank(int *arr, int len){
    long long total=0;
    for (int d=1; d<=*digit_array; d++){
        for (int i=1; i<=min(len,d); i++){
            for (int j=(i==1?1:0); j<arr[i]; j++){
                long long leftPart=0, rightPart=0;
                for (int p=1; p<i; p++)
                    leftPart=rightPart=leftPart*10+arr[p];
                leftPart=rightPart=leftPart*10+j;
                for (int p=i+1; p<=d; p++)
                    leftPart=leftPart*10, rightPart=rightPart*10+9;
                rightPart=min(rightPart, total_value);
                if (leftPart<=rightPart)
                    total+=rightPart-leftPart+1;
            }
        }
        if (d<=len) ++total;
    }
    return total;
}

int computeF(int *arr, int len){
    return ((-get_number(arr,len)+calculate_rank(arr,len))%MOD1+MOD1)%MOD1;
}

int diff_vals[15];
int q1_list[1000010], q2_list[1000010];
long long q2_sum_arr[1000010];

void dfs_range(int start, int end, int *q, int v){
    if (start==end){
        for (int i=0; i<=9; i++)
            q[++*q]=(v+1LL*i*diff_vals[start])%MOD1;
        return;
    }
    for (int i=0; i<=9; i++)
        dfs_range(start+1, end, q, (v+1LL*i*diff_vals[start])%MOD1);
}

void perform_update(int len, int idx, int val){
    int backup[15];
    memcpy(backup, digit_array, sizeof(digit_array));
    digit_array[idx]=val;
    for (int p=idx+1; p<=len; p++) digit_array[p]=0;
    int baseVal=computeF(digit_array,len);
    for (int p=idx+1; p<=len; p++){
        digit_array[p]=1;
        diff_vals[p]=(computeF(digit_array,len)+MOD1-baseVal)%MOD1;
        digit_array[p]=0;
    }
    if (len-idx==0){
        total_ans=(total_ans+baseVal)%MOD2;
        return;
    }
    if (len-idx==1){
        for (int p=0; p<=9; p++)
            total_ans=(total_ans+(baseVal+1LL*p*diff_vals[len])%MOD1)%MOD2;
        return;
    }
    int mid=(len+idx)/2;
    *q1_list=0; *q2_list=0;
    dfs_range(idx+1, mid, q1_list, baseVal);
    dfs_range(mid+1, len, q2_list, 0);
    std::sort(q2_list+1, q2_list+*q2_list+1);
    long long sumQ2=0;
    for (int i=1; i<=*q2_list; i++)
        sumQ2=(sumQ2+q2_list[i])%MOD2;
    for (int i=1; i<=*q1_list; i++){
        int p=lower_bound(q2_list+1, q2_list+*q2_list+1, MOD1 - q1_list[i]) - q2_list;
        total_ans=(total_ans+sumQ2+1LL*(*q2_list)*q1_list[i])%MOD2;
        total_ans=(total_ans+1LL*((*q2_list)-p+1)*(MOD2-MOD1))%MOD2;
    }
}

int main(){
    scanf("%lld", &total_value);
    long long m=total_value;
    for (*digit_array=0; m; m/=10) digit_array[++*digit_array]=m%10;
    std::reverse(digit_array+1, digit_array+*digit_array+1);
    for (int d=1; d<=*digit_array; d++){
        for (int i=1; i<=d; i++){
            int l=(i==1?1:0);
            int r=(d==*digit_array?digit_array[i]-1:9);
            for (int j=l; j<=r; j++)
                if (j!=digit_array[i]) perform_update(d, i, j);
        }
        total_ans=(total_ans+computeF(digit_array, d))%MOD2;
    }
    printf("%d\n", total_ans);
}
